import pandas as pd

def clean(df):
    valid_regions = {'North', 'South', 'East', 'West'}
    df = df[df['Region'].str.strip().isin(valid_regions)]
    df = df[(df['Quantity'].astype(int) == df['Quantity']) & (df['Quantity'] >= 1)]
    return df

def answer(df):
    return df.groupby('Region')['Quantity'].sum().to_dict()
